"""What a scene's generated bytes can reach. CONTRACT.md section 3.

ownership.py calls a scene's DOM region and JS block local only if nothing in them can change a frame outside the scene's own interval.
A region must be one balanced element, the scene's root, because a scene's window controls that root's opacity, and only what sits inside it stops at the window.
Writes are never inferred. A block is confined only if all it does is on a short list: tl.to, tl.set, tl.from and tl.fromTo with a numeric position, the declared helpers,
and plain arithmetic on its own names. It reads nothing else, so a shell table cannot change under it, and it cannot change one under the shell.
Anything else goes back in the shell, so changing it touches everything. That costs time, never a wrong picture.
A few things no hash of the block's own text can cover, because their effect depends on text elsewhere. Those raise ValueError and stop the build.
"""
import math, re
from html.parser import HTMLParser

COMMENT_OR_STRING = re.compile(r"""//[^\n]*|/\*.*?\*/|"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'""", re.S)
NAME = r"[A-Za-z_$][\w$]*"
OPENS, CLOSES = "([{", ")]}"

# args a timeline call needs before its position is explicit. The first four are what a confined block may call.
TL_WRITES = ("to", "set", "from", "fromTo")
TL_ARGS = {"to": 3, "set": 3, "from": 3, "fromTo": 4, "call": 3, "add": 2, "addLabel": 2, "addPause": 1}
CHAINED = re.compile(r"\)\s*\.\s*(to|set|from|fromTo|call|add|addLabel|addPause)\s*\(")
CALLBACK = re.compile(r"\bon(?:Update|Complete|Start|Repeat|ReverseComplete|Interrupt)\b|\bcallbackScope\b")
STYLE_WRITE = re.compile(r"\.\s*style\b")
SAFE_METHODS = {"forEach", "map", "filter", "slice", "concat", "join", "includes", "indexOf", "floor", "ceil", "round", "min", "max", "abs", "sqrt", "pow", "sin", "cos"}
SAFE_PROPERTIES = {"length", "PI"}
# The only names a confined block may read that it did not bind, with the declared helpers. Every shell constant and every global is off this list, so none needs naming.
BLOCK_WORDS = {"tl", "Math", "const", "let", "var", "function", "return", "if", "else", "for", "of", "in", "do", "while", "typeof", "true", "false", "null", "undefined"}
WORD = re.compile(rf"(?<![\w$]){NAME}")
METHOD = re.compile(rf"\.\s*({NAME})\s*\(")
PROPERTY = re.compile(rf"(?<![.])\.\s*({NAME})(?!\s*\()(?![\w$])")
TL_USE = re.compile(r"(?<![\w$.])tl(?![\w$])(?:\s*\.\s*([\w$]+))?")
TL_END = re.compile(r"(?<![\w$.])tl$")
STRING_MEMBER = re.compile(r'''[\w$)\]]\s*\[\s*""\s*\]''')
ASSIGN = re.compile(r"(?<![=!<>])(?:\*\*|<<|>>>?|&&|\|\||\?\?|[-+*/%&|^])?=(?![=>])")
STEP = re.compile(r"\+\+|--")
FUNCTION = re.compile(rf"\(([^()]*)\)\s*=>|({NAME})\s*=>|\bfunction\b\s*([\w$]*)\s*\(([^()]*)\)")
DECLARE = re.compile(r"(?<![\w$.])(const|let|var|function|class)(?![\w$])")
LIST_CALL = re.compile(r"\.\s*(?:forEach|map|filter)\s*\($")
NAMED = re.compile(rf"(?:const|let|var)\s+({NAME})\s*=$")
SLICED = re.compile(rf"(?<![\w$.])({NAME})\s*\.\s*slice\s*\([^()]*\)$")
NUMBER = re.compile(r"\d+\.?\d*|\.\d+")
BEFORE_REGEX = "(,=:[!&|?{};+-*%<>~^"
MARK = re.compile(r"^[ \t]*own\(.*\);[ \t]*$", re.M)

REGION_END = "beat-region-end"
VOID = {"img", "br"}
HTML_TAGS = {"div", "span", "p", "b", "i", "em", "strong", "br", "img", "video"}
SVG_TAGS = {"svg", "g", "path", "rect", "circle", "ellipse", "line", "polyline", "polygon", "text", "tspan", "use", "symbol", "lineargradient", "radialgradient", "stop", "clippath", "mask"}
ATTRS = {"id", "class", "style", "src", "alt", "href", "xlink:href", "muted", "playsinline", "data-start", "data-duration", "data-media-start", "data-track-index",
         "data-layout-allow-overflow", "data-layout-allow-overlap", "viewbox", "preserveaspectratio", "d", "points", "x", "y", "x1", "y1", "x2", "y2", "cx", "cy", "r", "rx", "ry", "width", "height",
         "transform", "pathlength", "fill", "fill-opacity", "fill-rule", "clip-rule", "stroke", "stroke-width", "stroke-opacity", "stroke-dasharray", "stroke-dashoffset", "stroke-linecap", "stroke-linejoin",
         "opacity", "offset", "stop-color", "stop-opacity", "gradientunits", "gradienttransform", "font-size", "font-family", "font-weight", "text-anchor", "dominant-baseline"}
ROOT_STYLE = re.compile(r"\s*opacity\s*:\s*[\d.]+\s*;?\s*")
URL_REF = re.compile(r"""url\(\s*['"]?#([^'")\s]+)""")
ID_REF = re.compile(r"""url\(\s*['"]?#([\w.:-]+)|href\s*=\s*['"]?#([\w.:-]+)""")
SELECTOR = re.compile(r"#([\w.:-]+)")
CAPTION_TAG = re.compile(r"<(?!/?b>)")


def code_only(text):
    """JS with comments gone and every string emptied, so the rest can be read by position."""
    return COMMENT_OR_STRING.sub(lambda m: "" if m[0][0] == "/" else '""', text)


def no_comments(text):
    return COMMENT_OR_STRING.sub(lambda m: "" if m[0][0] == "/" else m[0], text)


def closing(code, at):
    """Index of the bracket that closes the one at code[at]."""
    stack = []
    for i in range(at, len(code)):
        c = code[i]
        if c in OPENS:
            stack.append(CLOSES[OPENS.index(c)])
        elif c in CLOSES:
            if not stack or stack.pop() != c:
                raise ValueError(f"a block ownership cannot read: unbalanced {c} in {code[max(0, i - 40):i + 1]!r}")
            if not stack:
                return i
    raise ValueError(f"a block ownership cannot read: unclosed {code[at]} in {code[at:at + 40]!r}")


def opening(code, at):
    """Index of the bracket that opens the one at code[at]."""
    depth = 0
    for i in range(at, -1, -1):
        depth += code[i] in CLOSES
        depth -= code[i] in OPENS
        if not depth:
            return i
    raise ValueError(f"a block ownership cannot read: unopened {code[at]} in {code[max(0, at - 40):at + 1]!r}")


def balanced(code):
    i = 0
    while i < len(code):
        if code[i] in OPENS:
            i = closing(code, i)
        elif code[i] in CLOSES:
            raise ValueError(f"a block ownership cannot read: unbalanced {code[i]} in {code[max(0, i - 40):i + 1]!r}")
        i += 1


def split_args(code, at):
    """The top-level arguments of the call whose ( is at code[at]."""
    end = closing(code, at)
    args, depth, start = [], 0, at + 1
    for i in range(at + 1, end):
        if code[i] in OPENS:
            depth += 1
        elif code[i] in CLOSES:
            depth -= 1
        elif code[i] == "," and depth == 0:
            args.append(code[start:i])
            start = i + 1
    last = code[start:end]
    return args + [last] if last.strip() or args else []


def pattern_names(text):
    """Names a destructuring pattern binds: {a, b: c, d = 1, ...e} and [f, , [g]]."""
    text = text.strip().lstrip(".").strip()
    if not text:
        return []
    if text[0] in "{[":
        inner = split_args("(" + text[1:closing(text, 0)] + ")", 0)
        out = []
        for part in inner:
            part = part.strip().lstrip(".").strip()
            if not part:
                continue
            if text[0] == "{" and ":" in part:
                part = part.split(":", 1)[1]
            out += pattern_names(part)
        return out
    m = re.match(NAME, text)
    return [m[0]] if m else []


def declarators(code, at):
    """A const, let or var list starting at code[at]: (name, its initialiser or None, where that starts) for each name, and where the list ends."""
    found = []
    i = at
    while True:
        while i < len(code) and code[i].isspace():
            i += 1
        if i >= len(code):
            return found, i
        if code[i] in "{[":
            end = closing(code, i)
            names = pattern_names(code[i:end + 1])
            i = end + 1
        else:
            m = re.compile(NAME).match(code, i)
            if not m:
                return found, i
            names = [m[0]]
            i = m.end()
        start = None
        rest = code[i:].lstrip()
        if rest[:1] == "=" and rest[1:2] not in ("=", ">"):
            start = len(code) - len(rest) + 1
        # past the initialiser, to the next comma or the end of the statement
        while i < len(code):
            c = code[i]
            if c in OPENS:
                i = closing(code, i) + 1
            elif c == ",":
                break
            elif c == ";" or c in CLOSES:
                break
            elif c == "\n":
                before, after = code[:i].rstrip()[-1:], code[i:].lstrip()[:1]
                if after == "," or before in tuple("=+-*/%&|^?:,<>"):
                    i += 1
                else:
                    break
            else:
                i += 1
        whole = len(names) == 1 and start is not None
        found += [(name, code[start:i].strip() if whole else None, start if whole else None) for name in names]
        if i < len(code) and code[i] == ",":
            i += 1
        else:
            return found, i


def top_names(block):
    """Names a block declares at its own top level, in any form. Deeper names are scoped, except var, which is not."""
    code = code_only(block)
    balanced(code)
    names, i = [], 0
    while True:
        m = DECLARE.search(code, i)
        if not m:
            return names
        i = m.end()
        depth = depth_at(code, m.start())
        if m[1] in ("function", "class"):
            found = re.compile(rf"\s+({NAME})").match(code, i)
            if found and depth == 0:
                names.append(found[1])
        elif depth == 0 or m[1] == "var":
            found, i = declarators(code, i)
            names += [row[0] for row in found]


def depth_at(code, at):
    depth = 0
    for c in code[:at]:
        depth += c in OPENS
        depth -= c in CLOSES
    return depth


def scope_of(code, at):
    """The braces around code[at], or the whole of it."""
    depth = 0
    for i in range(at - 1, -1, -1):
        if code[i] in CLOSES:
            depth += 1
        elif code[i] in OPENS:
            if depth:
                depth -= 1
            elif code[i] == "{":
                return i, closing(code, i)
    return 0, len(code)


def expression_end(code, at):
    """Where the expression starting at code[at] stops."""
    i = at
    while i < len(code):
        if code[i] in OPENS:
            i = closing(code, i)
        elif code[i] in CLOSES or code[i] in ",;":
            return i
        i += 1
    return i


def functions(code):
    """Each function in code: its parameters as written, its name if it has one, and the span they are bound in."""
    found = []
    for m in FUNCTION.finditer(code):
        arrow = m[4] is None
        params = (m[1] if m[1] is not None else m[2]) if arrow else m[4]
        at = m.end()
        while at < len(code) and code[at].isspace():
            at += 1
        end = closing(code, at) if code[at:at + 1] == "{" else expression_end(code, at)
        found.append({"name": m[3] or None, "params": split_args(f"({params})", 0), "start": m.start(), "end": end, "arrow": arrow})
    return found


def bindings(code):
    """Everything code binds, each with the span it is bound in, so a parameter does not stand for the same name outside its function. Const, let and function names take their braces, var all of it."""
    binds, i = [], 0
    while True:
        m = DECLARE.search(code, i)
        if not m:
            break
        i = m.end()
        first, last = (0, len(code)) if m[1] == "var" else scope_of(code, m.start())
        if m[1] in ("const", "let", "var"):
            found, i = declarators(code, i)
            binds += [{"name": name, "first": first, "last": last, "value": value, "at": at, "param": False} for name, value, at in found]
        else:
            found = re.compile(rf"\s+({NAME})").match(code, i)
            if found:
                binds.append({"name": found[1], "first": first, "last": last, "value": None, "at": None, "param": False})
    for fn in functions(code):
        binds += [{"name": name, "first": fn["start"], "last": fn["end"], "value": None, "at": None, "param": True} for param in fn["params"] for name in pattern_names(param)]
    return binds


def bound(binds, name, at):
    return any(b["name"] == name and b["first"] <= at <= b["last"] for b in binds)


def words(code):
    """Each name code uses as a value, and where. Not a property after a dot, and not a key in an object literal. A spread is a read."""
    for m in WORD.finditer(code):
        before = code[:m.start()].rstrip()
        if before.endswith(".") and not before.endswith("..."):
            continue
        if code[m.end():].lstrip()[:1] == ":" and before[-1:] in ("{", ","):
            continue
        yield m[0], m.start()


def writes(code):
    """Each write in code that is not a declaration's own initialiser: (name, stays a number, where). Name None is a write through a member or a pattern."""
    initialisers = {b["at"] - 1 for b in bindings(code) if b["at"] is not None}
    found = []

    def target(left):
        """The plain name left ends with, None for a member, "" for a destructuring declaration, which binds and writes nothing else."""
        if left[-1:] in ("]", "}", ")"):
            declared = left[-1] != ")" and re.search(r"(?<![\w$.])(?:const|let|var)$", left[:opening(left, len(left) - 1)].rstrip())
            return "" if declared else None
        m = re.search(rf"(?<![\w$])({NAME})$", left)
        return None if m is None or left[:m.start()].rstrip().endswith(".") else m[1]

    for m in ASSIGN.finditer(code):
        name = None if m.end() - 1 in initialisers else target(code[:m.start()].rstrip())
        if m.end() - 1 not in initialisers and name != "":
            found.append((name, False, m.start()))
    for m in STEP.finditer(code):
        left = code[:m.start()].rstrip()
        if re.search(r"[\w$\])]$", left):
            found.append((target(left), True, m.start()))
        else:
            after = re.match(rf"\s*({NAME})\s*([.\[]?)", code[m.end():])
            found.append((after[1] if after and not after[2] else None, True, m.end()))
    return found


def regex_literal(code):
    """A / where a value should start. Its text is not code, and a quote inside one would read as the start of a string."""
    for m in re.finditer("/", code):
        before = code[:m.start()].rstrip()
        if not before or before[-1] in BEFORE_REGEX or re.search(r"(?<![\w$.])(?:return|typeof|in|of|else|do)$", before):
            return True
        if before[-1] == ")" and re.search(r"(?<![\w$.])(?:if|while|for)$", before[:opening(before, len(before) - 1)].rstrip()):
            return True
    return False


def frame_gaps(code, fps=60):
    """Advisory (selector, show time) pairs. Reads direct timeline calls and ivory's arrival helpers, including cutIn's fIn. Literal times are compared on the requested grid;
    matching parameter expressions are reported conservatively. This is not an interpreter for arbitrary project JavaScript."""
    code = no_comments(code)
    shows, tweens = [], []
    masked = COMMENT_OR_STRING.sub(lambda m: " " * len(m[0]), code)
    scopes = []
    for m in re.finditer(rf"\bfunction\s+{NAME}\s*\([^()]*\)\s*\{{", masked):
        at = m.end() - 1
        scopes.append((at, closing(masked, at)))
    def scope_at(at):
        return next((a for a, b in reversed(scopes) if a < at < b), None)
    def selector(text):
        text = text.strip()
        return text[1:-1] if len(text) > 1 and text[0] in "\"'" and text[-1] == text[0] else text
    def related(a, b):
        a, b = selector(a), selector(b)
        return b == a or any(b.startswith(a + sep) for sep in (" ", ">", "+", " +"))
    def moment(text):
        text = text.strip()
        early = re.fullmatch(r"A\((.*)\)", text)
        try:
            return float(early[1] if early else text) - (0.004 if early else 0)
        except ValueError:
            return None
    for m in re.finditer(r"(?<![\w$.])show\s*\(", code):
        args = split_args(code, m.end() - 1)
        if len(args) == 2 and not code[max(0, m.start() - 12):m.start()].rstrip().endswith("function"):
            shows.append((args[0].strip(), args[1].strip(), scope_at(m.start())))
    for m in TL_USE.finditer(code):
        need = TL_ARGS.get(m[1])
        opening_at = code.find("(", m.end())
        if m[1] not in TL_WRITES or need is None or opening_at < 0 or code[m.end():opening_at].strip():
            continue
        args = split_args(code, opening_at)
        if len(args) < need:
            continue
        sel, t = args[0].strip(), args[need - 1].strip()
        scope = scope_at(m.start())
        early = re.fullmatch(r"A\((.*)\)", t)
        if m[1] == "set" and early and re.search(r"\bopacity\s*:\s*1\b", args[1]):
            if (sel, early[1], scope) not in shows:
                shows.append((sel, early[1], scope))
        else:
            tweens.append((sel, t, moment(t), scope))
    # A helper with no declaration here has the stock ivory timing. If fIn is present, read whether it shares A's offset.
    aligned_cut = bool(re.search(r"const\s+fIn\s*=.*(?:t\s*-\s*0\.004|A\(t\))", code))
    for m in re.finditer(r"(?<![\w$.])(?:on|rise|pop|word|cutIn|drawPath)\s*\(", code):
        if code[max(0, m.start() - 12):m.start()].rstrip().endswith("function"):
            continue
        args = split_args(code, m.end() - 1)
        if len(args) < 2:
            continue
        sel, t = args[0].strip(), args[1].strip()
        at = moment(t)
        if m[0].startswith("cutIn") and at is not None:
            at = math.ceil((at - (0.004 if aligned_cut else 0)) * fps - 1e-6) / fps
        tweens.append((sel, t, at, scope_at(m.start())))
    rows = []
    for sel, t, scope in shows:
        at = moment(t)
        if at is None:
            hit = any(other == scope and related(sel, s) and when == t for s, when, _, other in tweens)
        else:
            first = math.ceil((at - 0.004) * fps - 1e-6) / fps
            candidates = [when for s, _, when, other in tweens if other == scope and related(sel, s) and when is not None and when >= at - 0.004 - 1e-9]
            hit = bool(candidates) and first < min(candidates) - 1e-9
        if hit and (sel, t) not in rows:
            rows.append((sel, t))
    return rows


def position_problems(code):
    """A tween with no explicit numeric position lands after whatever tween came last, so it depends on text in other blocks. No hash of its own block can cover that."""
    problems = [f".{m[1]}() chained after another call" for m in CHAINED.finditer(code)]
    for m in TL_USE.finditer(code):
        need = TL_ARGS.get(m[1])
        if need is None:
            continue
        opening_at = code.find("(", m.end())
        if opening_at < 0 or code[m.end():opening_at].strip():
            continue
        args = split_args(code, opening_at)
        if len(args) < need:
            problems.append(f"tl.{m[1]}() with no position")
        elif '""' in outside_calls(args[need - 1]):
            problems.append(f"tl.{m[1]}() with a label or relative position")
    return problems


def outside_calls(arg):
    """An expression with what sits in brackets removed. A string in A(at("strip")) picks a number, and a string at the top of a position is a label."""
    while True:
        cut = re.sub(r"\([^()]*\)", "", arg)
        if cut == arg:
            return cut
        arg = cut


class Numbers:
    """Which expressions in a block can only be numbers. A string or undefined in a position lands relative to whatever tween came last, in another block.

    Read by place, so `t` in one callback is not `t` in the next. A name counts only if every value it can hold was seen and is a number: a numeric constant, a parameter fed from a literal array,
    or a parameter of the block's own function when every call passes one. trust_names False is for a block that is not confined: it can change its own names in ways this cannot see, so only literal arithmetic counts.
    """

    def __init__(self, code, helpers, trust_names=True):
        self.code, self.helpers, self.trust_names = code, helpers, trust_names
        self.fns = functions(code)
        self.binds = bindings(code)
        self.changed = {name for name, stays_a_number, _ in writes(code) if not stays_a_number}
        self.busy = set()

    def number(self, expr, at):
        expr = expr.strip()
        operands, depth, start = [], 0, 0
        for i, c in enumerate(expr):
            depth += c in OPENS
            depth -= c in CLOSES
            if depth == 0 and c in "+-*/%":
                operands.append(expr[start:i])
                start = i + 1
        operands = [x for x in operands + [expr[start:]] if x.strip()]
        if not operands:
            return False
        if operands != [expr]:
            return all(self.number(x, at) for x in operands)
        if NUMBER.fullmatch(expr):
            return True
        if expr[0] == "(" and closing(expr, 0) == len(expr) - 1:
            return self.number(expr[1:-1], at)
        m = re.fullmatch(r"A\s*(\(.*\))", expr, re.S)
        if m and "A" in self.helpers and not bound(self.binds, "A", at) and closing(m[1], 0) == len(m[1]) - 1:
            args = split_args(m[1], 0)
            return len(args) == 1 and self.number(args[0], at)
        m = re.fullmatch(rf"({NAME})\s*\.\s*length", expr)
        if m:
            return self.rows(m[1]) is not None
        return bool(re.fullmatch(NAME, expr)) and self.name(expr, at)

    def name(self, name, at):
        if not self.trust_names or name in self.changed:
            return False
        declared = [b for b in self.binds if b["name"] == name and not b["param"]]
        inner = [f for f in self.fns if f["start"] <= at <= f["end"] and name in [n for p in f["params"] for n in pattern_names(p)]]
        fn = max(inner, key=lambda f: f["start"], default=None)
        if not declared and fn is None:
            return False
        key = (name, fn["start"] if fn else None)
        if key in self.busy:
            return False
        self.busy.add(key)
        try:
            return all(b["value"] is not None and self.number(b["value"], b["at"]) for b in declared) and (fn is None or self.parameter(fn, name))
        finally:
            self.busy.discard(key)

    def parameter(self, fn, name):
        place = None
        for k, text in enumerate(fn["params"]):
            text = text.strip()
            if text == name:
                place = (k, None)
            elif text[:1] == "[":
                column = [x.strip() for x in split_args("(" + text[1:closing(text, 0)] + ")", 0)]
                if name in column:
                    place = (k, column.index(name))
        if place is None:
            return False
        k, column = place
        before = self.code[:fn["start"]].rstrip()
        listed = LIST_CALL.search(before)
        if listed:
            if k == 1 and column is None:
                return True  # the index
            rows = self.rows(before[:listed.start()]) if k == 0 else None
            if rows is None:
                return False
            if column is None:
                return all(self.number(row, fn["start"]) for row in rows)
            return all(row.strip()[:1] == "[" and self.column(row.strip(), column, fn["start"]) for row in rows)
        named = NAMED.search(before)
        caller = named[1] if named else fn["name"]
        return bool(caller) and self.calls(caller, k)

    def column(self, row, column, at):
        cells = split_args("(" + row[1:closing(row, 0)] + ")", 0)
        return column < len(cells) and self.number(cells[column], at)

    def rows(self, text):
        """The elements of the array text ends with: a literal, a constant holding one, or a slice of that. None for anything else."""
        text = text.rstrip()
        m = SLICED.search(text) or re.search(rf"(?<![\w$.])({NAME})$", text)
        if m:
            held = [b for b in self.binds if b["name"] == m[1]]
            if len(held) != 1 or held[0]["param"] or held[0]["value"] is None or m[1] in self.changed:
                return None
            return self.rows(held[0]["value"])
        if not text.endswith("]"):
            return None
        start = opening(text, len(text) - 1)
        if re.search(r"[\w$)\]]$", text[:start].rstrip()):
            return None  # an index, not a literal
        return split_args("(" + text[start + 1:-1] + ")", 0)

    def calls(self, name, k):
        """True if the block's own function name is only ever called, with a number at argument k."""
        for word, at in words(self.code):
            if word != name or re.search(r"(?<![\w$.])(?:const|let|var|function)$", self.code[:at].rstrip()):
                continue
            start = at + len(name)
            while start < len(self.code) and self.code[start].isspace():
                start += 1
            if self.code[start:start + 1] != "(":
                return False
            args = split_args(self.code, start)
            if len(args) <= k or not self.number(args[k], start):
                return False
        return True


def block_reach(block, helpers):
    """Why this block is not confined. An empty list means all it does is on the short list."""
    code = code_only(MARK.sub("", block, 1))
    binds = bindings(code)
    why = []
    if "`" in code:
        why.append("template literal")
    if "\\" in code or not code.isascii():
        why.append("a name this cannot read")
    if regex_literal(code):
        why.append("regular expression")
    if code.count("=>") != sum(f["arrow"] for f in functions(code)):
        why.append("a function this cannot read")
    why += [f"sets {m[0]}" for m in CALLBACK.finditer(code)]
    if STYLE_WRITE.search(code):
        why.append("touches .style")
    why += [f"rebinds {b['name']}" for b in binds if b["name"] in BLOCK_WORDS or b["name"] in helpers]
    for name, at in words(code):
        if name not in BLOCK_WORDS and name not in helpers and not bound(binds, name, at):
            why.append(f"uses {name}")
    for m in TL_USE.finditer(code):
        if m[1] not in TL_WRITES:
            why.append(f"tl.{m[1]}" if m[1] else "uses tl directly")
    for m in METHOD.finditer(code):
        if m[1] in TL_WRITES:
            if not TL_END.search(code[:m.start()].rstrip()):
                why.append(f".{m[1]}() on something other than tl")
        elif m[1] not in SAFE_METHODS:
            why.append(f"calls .{m[1]}()")
    why += [f"reads .{m[1]}" for m in PROPERTY.finditer(code) if m[1] not in SAFE_PROPERTIES]
    if STRING_MEMBER.search(code):
        why.append("a member named by a string")
    for name, _, at in writes(code):
        if name is None:
            why.append("writes through a member")
        elif not bound(binds, name, at):
            why.append(f"assigns {name}")
    return list(dict.fromkeys(why))


def block_problems(block, helpers, found):
    """What stops the build in one block. found: block_reach's answer. A position has to be a number, and a tween placed any other way cannot be read, so tl and the helpers are only ever called."""
    code = code_only(MARK.sub("", block, 1))
    problems = position_problems(code)
    numbers = Numbers(code, helpers, not found)
    for m in TL_USE.finditer(code):
        need = TL_ARGS.get(m[1])
        start = code.find("(", m.end())
        direct = start >= 0 and not code[m.end():start].strip()
        if m[1] is None or (need and not direct):
            problems.append("tl used other than by a call")
        elif need:
            args = split_args(code, start)
            if len(args) >= need and not numbers.number(args[need - 1], start):
                problems.append(f"tl.{m[1]}() with a position that is not a number")
    for name, at in words(code):
        if name not in helpers:
            continue
        start = at + len(name)
        while start < len(code) and code[start].isspace():
            start += 1
        if code[start:start + 1] != "(":
            problems.append(f"{name} used other than by a call")
            continue
        need = helpers.get(name) if hasattr(helpers, "get") else None
        if need:
            args = split_args(code, start)
            if len(args) < need:
                problems.append(f"{name}() with no time")
            elif not numbers.number(args[need - 1], start):
                problems.append(f"{name}() with a time that is not a number")
    return problems


class Region(HTMLParser):
    """A region as a page reads it. shape: what stops the build. reach: what keeps it in the shell.

    A page's own rules decide what a tag does, so only tags whose rules are simple are on the list. `<div/>` does not close a div, a tag left open at the end is dropped by this parser
    and not by a page, and a browser runs on past an unclosed <textarea>. REGION_END is fed after the region, so anything unterminated swallows it and shows.
    """

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.open, self.top, self.ids, self.refs, self.shape, self.reach, self.ended = [], [], [], [], [], [], False

    def element(self, tag, attrs):
        if self.ended:
            self.shape.append(f"<{tag}> after the end of the region")
        names = [k for k, _ in attrs]
        if len(set(names)) != len(names):
            self.shape.append(f"<{tag}> has one attribute twice")
        if not self.open:
            self.top.append((tag, dict(attrs)))
        inside_svg = "svg" in self.open
        if inside_svg and tag in HTML_TAGS:
            self.shape.append(f"<{tag}> inside an svg leaves the svg")
        if tag not in SVG_TAGS and (inside_svg or tag not in HTML_TAGS):
            self.reach.append(f"contains <{tag}>")
        for k, v in attrs:
            v = v or ""
            if k not in ATTRS:
                self.reach.append(f"<{tag}> has {k}")
            if "javascript:" in re.sub(r"\s", "", v).lower():
                self.reach.append(f"<{tag}> has a script in {k}")
            if k == "id":
                self.ids.append(v)
            if k in ("href", "xlink:href") and v.startswith("#"):
                self.refs.append(v[1:])
            self.refs += URL_REF.findall(v)

    def handle_starttag(self, tag, attrs):
        if tag == REGION_END:
            if self.ended:
                self.shape.append(f"<{REGION_END}> in the region")
            self.ended = True
            return
        self.element(tag, attrs)
        if tag not in VOID:
            self.open.append(tag)

    def handle_startendtag(self, tag, attrs):
        self.element(tag, attrs)
        if tag not in VOID and tag != "svg" and "svg" not in self.open:
            self.shape.append(f"<{tag}/> does not close in a page")

    def handle_endtag(self, tag):
        if self.open[-1:] != [tag]:
            self.shape.append(f"</{tag}> closes nothing open")
        else:
            self.open.pop()

    def text(self, data):
        if "<" in data:
            self.shape.append("a bare < in text")
        if not self.open and data.strip():
            self.shape.append(f"text outside the root: {data.strip()[:30]!r}")

    def handle_data(self, data):
        self.text(data)

    def handle_entityref(self, name):
        self.text("&")

    def handle_charref(self, name):
        self.text("&")

    def handle_comment(self, data):
        self.reach.append("contains a comment")

    def handle_decl(self, decl):
        self.reach.append("contains a declaration")

    def handle_pi(self, data):
        self.reach.append("contains a declaration")

    def unknown_decl(self, data):
        self.reach.append("contains a declaration")


def root_of(id_):
    return id_.split(".", 1)[-1]


def read_region(id_, dom):
    """The parsed region. Raises ValueError unless it is one balanced element and that element is the owner's root."""
    region = Region()
    try:
        region.feed(f"{dom}<{REGION_END}>")
        region.close()
    except AssertionError as e:
        raise ValueError(f"{id_}: a region ownership cannot read: {e}")
    problems = list(region.shape)
    if not region.ended:
        problems.append("something is left unterminated")
    problems += [f"<{tag}> is not closed" for tag in region.open]
    if len(region.top) != 1:
        problems.append(f"{len(region.top)} top-level elements, not 1")
    elif region.top[0][1].get("id") != root_of(id_):
        problems.append(f"its one element is not #{root_of(id_)}")
    if problems:
        raise ValueError(f"{id_}: {'; '.join(dict.fromkeys(problems))}")
    # What the root's own attributes do is not bounded by the root. A window is its opacity, and `display:contents` or a new class changes what that hides
    for k, v in region.top[0][1].items():
        if k == "style" and not ROOT_STYLE.fullmatch(v or ""):
            region.reach.append("the root has a style beyond its opacity")
        elif k not in ("id", "class", "style"):
            region.reach.append(f"the root has {k}")
    return region


class Ids(HTMLParser):
    """Every id in the shell's DOM. Lenient, because the shell is the whole page."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.ids = set()

    def handle_starttag(self, tag, attrs):
        self.ids.update(v for k, v in attrs if k == "id" and v)


def shell_names(shell):
    """Every id the shell holds or looks up. A region defining one takes it over, because $() and a selector find the first match in the page."""
    page = Ids()
    page.feed(shell)
    page.close()
    script = no_comments(shell[shell.rindex("<script>"):]) if "<script>" in shell else ""
    return page.ids | set(SELECTOR.findall(script))


def id_reach(regions, blocks, shell):
    """An owner defining something another owner, or the shell, points at. Its text is not local, because a change to it shows elsewhere."""
    defined = {}
    for id_, region in regions.items():
        for name in region.ids:
            if name in defined and defined[name] != id_:
                raise ValueError(f"id {name} is in both {defined[name]} and {id_}: a selector would reach the wrong one")
            defined[name] = id_
    names = shell_names(shell)
    for name, id_ in defined.items():
        if name in names and name != root_of(id_):
            raise ValueError(f"{id_} defines #{name}, and the shell uses that id: its lookups would reach the scene's element")
    why = {}
    readers = {id_: region.refs + SELECTOR.findall(no_comments(blocks.get(id_, ""))) for id_, region in regions.items()}
    readers["shell"] = [a or b for a, b in ID_REF.findall(shell)]
    for reader, names in readers.items():
        for name in names:
            owner = defined.get(name)
            if owner and owner != reader:
                why.setdefault(owner, []).append(f"{reader} points at #{name}")
    return why


def caption_reach(rows):
    """A caption row is confined only if its markup is the plain accent tag."""
    return [row[4] for row in rows if CAPTION_TAG.search(row[2])]


def reach(doms, blocks, shell, helpers=()):
    """owner id -> why its text must stay in the shell. Raises ValueError on what no hash of one block can cover."""
    why = {}
    regions = {id_: read_region(id_, dom) for id_, dom in doms.items()}
    for id_, block in blocks.items():
        found = block_reach(block, helpers)
        problems = block_problems(block, helpers, found)
        if problems:
            raise ValueError(f"{id_}: {'; '.join(dict.fromkeys(problems))}")
        if found:
            why[id_] = found
    for id_, region in regions.items():
        if region.reach:
            why[id_] = why.get(id_, []) + list(dict.fromkeys(region.reach))
    for id_, found in id_reach(regions, blocks, shell).items():
        why[id_] = why.get(id_, []) + found
    return why
